document.addEventListener('alpine:init', () => {
    Alpine.data('common', () => ({
        formOffsetTop: window.innerWidth >= 1024 ? 120 : 80,

        init() {
            Livewire.on('triggerModal', (open) => {
                this.triggerModal(open[0]);
            });

            document.addEventListener('triggermodal', (event) => {
                this.triggerModal(event.detail.open);
            });

            $('.wechat').click(() => {
                if (navigator.userAgent.match(/Android|BlackBerry|iPhone|iPad|iPod|Opera Mini|IEMobile/i)) {
                    window.open('https://mp.weixin.qq.com/s/-brXwtUiH8kc-Pk4LRsdrQ', '_blank').focus();
                } else {
                    this.$dispatch('openwechat')
                }
            });
        },

        triggerFormResize() {
            this.formOffsetTop = window.innerWidth >= 1024 ? 120 : 80;
        },

        triggerModal(open) {
            document.documentElement.classList.toggle('overflow-hidden', open);
        }
    }));
});

Livewire.hook('commit', ({fail}) => {
    fail(({preventDefault}) => {
        preventDefault();
    })
})

document.addEventListener('alpine:init', () => {
    Alpine.data('visaApplication', () => ({
        selectedChoice: '',
        modalOpened: false,

        init() {
            const handleModalFocus =  document.addEventListener('keydown', e => {
                if (e.key === 'Tab') {
                    const focused = document.querySelector(':focus')

                    if(focused?.getAttribute('wire:click') === 'triggerSearch(false)') {
                        e.preventDefault();
                        document.querySelector('#visa_filter_button').focus()
                    }
                }
                if (e.key === 'Escape') {
                    window.Livewire.find('AgTC6CgLwYkuFSso6Ifm').call('triggerOpen')
                }
            });

            document.removeEventListener('keydown', handleModalFocus);

            this.updateSelectedChoice('');

            if (window.location.hash === '#tool') {
                window.Livewire.find('AgTC6CgLwYkuFSso6Ifm').set('opened', true);
                const visaTop = document.getElementById('visa_top');
                const offsetY = 140;
                if (visaTop) {
                    const y = visaTop.getBoundingClientRect().top + window.pageYOffset - offsetY;
                    window.scrollTo({ top: y, behavior: 'smooth' });
                }
            }

            Livewire.on('updated_suitable_scheme', () => {
                setTimeout(() => {
                    aos.init({once: true});
                }, 500);

                $([document.documentElement, document.body]).animate({
                    scrollTop: $(`#schemes`).offset().top - this.formOffsetTop
                }, 1000);
            });

            Livewire.on('question_submission', (q) => {
                dataLayer.push({
                    event      : 'question_submission',
                    question_no: q[0]
                });
            })
        },

        updateSelectedChoice(value) {
            this.selectedChoice = value;
            window.Livewire.find('AgTC6CgLwYkuFSso6Ifm').set('selected_choice', this.selectedChoice);
        },

        updateOpened() {
            window.Livewire.find('AgTC6CgLwYkuFSso6Ifm').set('opened', true);
        },

        dataLayerPush(type, name) {
            dataLayer.push({
                event      : type,
                scheme_name: name
            });
        }
    }))
})

